const IN_NAME: i32 = 2;
/// Per character skipped between two matched characters.
const GAP: i32 = 1;

const NONE: i32 = i32::MIN / 2;

fn is_separator(c: char) -> bool {
    matches!(c, '/' | '\\' | '-' | '_' | ' ' | '.' | ':')
}

fn fold(c: char) -> char {
    c.to_lowercase().next().unwrap_or(c)
}

