                Item::Recent(dir) => {
                    let is_current = current.as_deref() == Some(dir.as_path());
                    let row = row
                        .id(("recent-project", ix))
                        .child(
                            Icon::new(if is_current {
                                IconName::Check
                            } else {
                                IconName::FolderClosed
                            })
                            .small()
                            .text_color(theme.muted_foreground),
                        )
                        .child(
                            v_flex()
                                .min_w_0()
                                .child(div().truncate().font_medium().child(folder_name(dir)))
                                .child(
                                    div()
                                        .truncate()
                                        .text_xs()
                                        .text_color(theme.muted_foreground)
                                        .child(dir.display().to_string()),
                                ),
                        );
                    // Lets UI tests find the row; inert in normal builds.
                    gpui_kit::TestSupportExt::test_support(row).into_any_element()
                }
                Item::OpenProject => {
                    let row = row
                        .id("open-project-from-recent")
                        .border_t_1()
                        .border_color(line)
                        .child(
                            Icon::new(IconName::FolderOpen)
                                .small()
                                .text_color(theme.muted_foreground),
                        )
                        .child("Open Project…");
                    gpui_kit::TestSupportExt::test_support(row).into_any_element()
                }
            }
        });

        let filter = h_flex()
            .gap_2()
            .px_3()
            .py_1()
            .border_b_1()
            .border_color(line)
            .child(
                Icon::new(IconName::Search)
                    .small()
                    .text_color(theme.muted_foreground),
            )
            .child(
                div()
                    .flex_1()
                    .child(Input::new(&list_state.filter).appearance(false).small()),
            );

        // Up and Down move the highlight, Enter picks it, and Escape closes the
        // list, before the filter takes them for itself.
        let list = v_flex()
            .id("recent-projects")
            .absolute()
            .left(bounds.left())
            .top(bounds.bottom())
            .w(bounds.size.width.max(LIST_WIDTH))
            .bg(block)
            .border_l_1()
            .border_r_1()
            .border_b_1()
            .border_color(edge)
            .shadow_md()
            .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
            .capture_key_down(cx.listener(|this, event: &KeyDownEvent, _, cx| {
                let keystroke = &event.keystroke;
                if keystroke.modifiers.modified() {
                    return;
                }
                match keystroke.key.as_str() {
                    "up" => this.step(-1, cx),
                    "down" => this.step(1, cx),
                    "enter" => {
                        let highlight = this.list.as_ref().map_or(0, |list| list.highlight);
                        this.pick(highlight, cx);
                    }
                    "escape" => this.close(cx),
                    _ => return,
                }
                cx.stop_propagation();
            }))
            .child(filter)
            .children(rows);

