        let cap = h_flex()
            .id("project-indicator-open")
            .absolute()
            .left(bounds.left())
            .top(bounds.top())
            .w(bounds.size.width)
            .h(bounds.size.height)
            .items_center()
            .gap_1p5()
            .px_3()
            .bg(block)
            .cursor_pointer()
            .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
            .on_click(cx.listener(|this, _, _, cx| this.close(cx)));
        let cap = Self::label_contents(cap, cx);

        let viewport = window.viewport_size();
        let overlay = div()
            .id("project-indicator-dim")
            .w(viewport.width)
            .h(viewport.height)
            .bg(crate::theme::dimming(cx))
            .occlude()
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|this, _, _, cx| this.close(cx)),
            )
            .child(cap)
            // Lets UI tests find the list; inert in normal builds.
            .child(gpui_kit::TestSupportExt::test_support(list));
        Some(
            deferred(anchored().position(point(px(0.), px(0.))).child(overlay)).with_priority(2),
        )
    }
